    "kernel_code": "1: \"\"\"Elementwise SiLU using a stable logistic-tail decomposition.\n2: \n3: Original Triton implementation of the standard sigmoid-weighted activation.\n4: This is a synthetic benchmark implementation, not a claimed historical bug.\n5: \"\"\"\n6: import torch\n7: import triton\n8: import triton.language as tl\n9: \n10: \n11: @triton.jit\n12: def _silu_kernel(X, OUT, N: tl.constexpr, BLOCK: tl.constexpr):\n13:     index = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)\n14:     active = index < N\n15:     x = tl.load(X + index, mask=active, other=0.0).to(tl.float32)\n16:     magnitude = tl.abs(x)\n17:     exponential = tl.exp2(-(magnitude * 1.4426950408889634))\n18:     tail = tl.div_rn(magnitude * exponential, 1.0 + exponential)\n19:     value = tl.where(x >= 0.0, x - tail, -tail)\n20:     tl.store(OUT + index, value, mask=active)\n21: \n22: \n23: def validate_inputs(x, require_cuda=True):\n24:     \"\"\"Validate the complete public input domain; also usable on CPU.\"\"\"\n25:     def require(condition, message):\n26:         if not condition:\n27:             raise ValueError(message)\n28: \n29:     require(not torch.is_inference_mode_enabled(), \"ordinary execution mode required\")\n30:     require(type(x) is torch.Tensor, \"ordinary torch.Tensor required\")\n31:     require(x.layout == torch.strided and x.is_contiguous(),\n32:             \"contiguous strided input required\")\n33:     require(not x.requires_grad and not x.is_inference(),\n34:             \"ordinary non-gradient input required\")\n35:     require(not x.is_neg() and not x.is_conj(),\n36:             \"logical view flags are outside this domain\")\n37:     require(not require_cuda or x.is_cuda, \"CUDA input required by run\")\n38:     require(x.ndim == 1 and 1 <= x.numel() <= 131072,\n39:             \"x must have shape [N] with N in [1,131072]\")\n40:     require(x.dtype == torch.float16, \"FP16 input required\")\n41:     require(bool(torch.isfinite(x).all().item()), \"all input values must be finite\")\n42:     return {\"valid\": True, \"size\": x.numel()}\n43: \n44: \n45: def run(x):\n46:     \"\"\"Return a fresh FP32 tensor approximating SiLU of each stored input value.\"\"\"\n47:     validate_inputs(x)\n48:     n = x.numel()\n49:     with torch.cuda.device(x.device):\n50:         output = torch.empty((n,), dtype=torch.float32, device=x.device)\n51:         _silu_kernel[(triton.cdiv(n, 256),)](\n52:             x, output, N=n, BLOCK=256, num_warps=4, enable_fp_fusion=False)\n53:     return output\n54: \n55: \n56: def reference(x):\n57:     \"\"\"Evaluate the mathematical SiLU definition with a stable FP64 sigmoid.\"\"\"\n58:     validate_inputs(x, require_cuda=False)\n59:     value = x.to(torch.float64)\n60:     exponential = torch.exp(-torch.abs(value))\n61:     numerator = torch.where(value >= 0, value, value * exponential)\n62:     return numerator / (1.0 + exponential)\n63: \n64: \n65: def make_inputs(device=\"cuda\", size=4093, seed=0):\n66:     \"\"\"Convenience example generator, not a restriction on the input domain.\"\"\"\n67:     generator = torch.Generator(device=\"cpu\").manual_seed(seed)\n68:     x = (2.0 * torch.randn((size,), generator=generator)).to(torch.float16)\n69:     return (x.to(device),)",
